// 08A — Interpret LTX Submission
// Classifies the submit response. NEVER retries a paid submission automatically.
const ctx = $('07A — Prepare Image-to-Video').isExecuted
  ? $('07A — Prepare Image-to-Video').first().json
  : $('07B — Prepare Text-to-Video').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep text */ } }
const apiErr = body && typeof body === 'object' && body.error ? body.error : null;
const now = new Date().toISOString();
const clip = (v) => String(v == null ? '' : (typeof v === 'string' ? v : JSON.stringify(v))).slice(0, 1500);

let accepted = false, error_status = null, detail = null, ambiguous = false;
if (status === 202 || status === 200 || status === 201) {
  if (body && body.id) accepted = true;
  else { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = 'LTX returned success without a job id: ' + clip(body); }
} else if (status === 401 || status === 403) { error_status = 'LTX_AUTH_ERROR'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : 'Authentication failed. Check the "LTX VIDEO API — THE SUMERIAN" credential.'; }
else if (status === 429) { error_status = 'LTX_RATE_LIMIT'; detail = (apiErr ? `${apiErr.type}: ${apiErr.message}` : 'Rate limited') + (r.headers && r.headers['retry-after'] ? ` (Retry-After ${r.headers['retry-after']}s)` : '') + '. Not retried automatically; resubmit later.'; }
else if (status === 402) { error_status = 'LTX_REQUEST_ERROR'; detail = 'insufficient_funds_error: LTX account has insufficient credits.'; }
else if (status && status >= 400 && status < 500) { error_status = 'LTX_REQUEST_ERROR'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : `HTTP ${status}: ${clip(body)}`; }
else if (status && status >= 500) { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = `LTX HTTP ${status} on submit. The job MAY have been created; not retried to avoid a duplicate charge. ${apiErr ? apiErr.type + ': ' + apiErr.message : ''}`; }
else { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = 'No HTTP response from LTX (network/timeout). The job MAY have been created; not retried to avoid a duplicate charge. ' + clip(r.error && (r.error.message || r.error)); }

return [{ json: {
  ...ctx,
  submission: { accepted, http_status: status, ltx_job_id: accepted ? body.id : null, ltx_created_at: accepted ? (body.created_at || null) : null, submitted_at: now, ambiguous },
  error_status, errors: error_status ? [{ field: 'ltx_submit', message: detail }] : [],
  has_reservation: true, already_responded: false,
  poll: accepted ? { attempts: 0, max_attempts: 45, interval_seconds: 20, max_elapsed_minutes: 20, transient_errors: 0, started_at: now } : null,
} }];

// 12 — Evaluate Job Status
// Bounded polling: stops after max_attempts or max_elapsed_minutes, whichever comes first.
const state = $('10 — Wait Before Poll').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep */ } }
const now = new Date();
const poll = { ...state.poll, attempts: (state.poll.attempts || 0) + 1, last_checked_at: now.toISOString(), last_http_status: status };
const elapsedMin = (now - new Date(state.poll.started_at)) / 60000;
const apiErr = body && typeof body === 'object' && body.error ? body.error : null;

let decision = 'CONTINUE', error_status = null, detail = null, job_status = body && body.status ? body.status : null;
if (status === 200 && body && body.status) {
  if (body.status === 'completed') decision = 'COMPLETED';
  else if (body.status === 'failed') { decision = 'ERROR'; error_status = 'LTX_JOB_FAILED'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : 'LTX reported the job as failed.'; }
  else decision = 'CONTINUE'; // pending | processing
} else if (status === 401 || status === 403) { decision = 'ERROR'; error_status = 'LTX_AUTH_ERROR'; detail = 'Authentication failed while polling.'; }
else if (status === 404) { decision = 'ERROR'; error_status = 'LTX_JOB_FAILED'; detail = 'Job not found (expired or unknown id).'; }
else { // 429 / 5xx / network: transient, keep polling within limits
  poll.transient_errors = (poll.transient_errors || 0) + 1;
  if (poll.transient_errors >= 6) { decision = 'ERROR'; error_status = status === 429 ? 'LTX_RATE_LIMIT' : 'UNKNOWN_ERROR'; detail = `Polling failed ${poll.transient_errors} times (last HTTP ${status}). Job ${state.submission.ltx_job_id} may still complete; check LTX before resubmitting.`; }
}
if (decision === 'CONTINUE' && (poll.attempts >= poll.max_attempts || elapsedMin >= poll.max_elapsed_minutes)) {
  decision = 'ERROR'; error_status = 'LTX_JOB_TIMEOUT';
  detail = `Job ${state.submission.ltx_job_id} still "${job_status}" after ${poll.attempts} polls / ${elapsedMin.toFixed(1)} min. Polling stopped. Record kept; do not resubmit the same version blindly.`;
}

return [{ json: {
  ...state, poll, decision, job_status,
  job: status === 200 ? body : null,
  error_status, errors: error_status ? [{ field: 'ltx_job', message: detail }] : [],
  has_reservation: true, already_responded: true,
} }];

// 13 — Capture Completed Output
const ctx = $input.first().json;
const job = ctx.job || {};
const result = job.result || {};
const url = result.video_url || Object.values(result).find((v) => typeof v === 'string' && /^https:\/\//.test(v)) || null;
const ok = typeof url === 'string' && url.startsWith('https://');
const completed_at = job.completed_at || new Date().toISOString();
const submittedMs = new Date(ctx.submission.submitted_at).getTime();
const metadata = {
  ltx_job_id: ctx.submission.ltx_job_id, ltx_created_at: job.created_at || ctx.submission.ltx_created_at, ltx_completed_at: job.completed_at || null,
  generation_seconds: Math.round((new Date(completed_at).getTime() - submittedMs) / 1000),
  poll_attempts: ctx.poll.attempts, result_keys: Object.keys(result),
  request: ctx.ltx_request.body.image_uri && ctx.ltx_request.body.image_uri.startsWith('data:')
    ? { ...ctx.ltx_request.body, image_uri: '[data-uri omitted]' } : ctx.ltx_request.body,
  estimated_cost_usd: ctx.ltx.estimated_cost_usd, cost_basis: `${ctx.ltx.duration}s × $${ctx.ltx.price_per_second_usd}/s (docs.ltx.io/pricing, ${ctx.ltx.pricing_verified})`,
  output_url_note: 'LTX output URLs expire. Download/archive the clip promptly.',
  warnings: ctx.warnings,
};
return [{ json: {
  ...ctx, output_ok: ok, output_url: url, completed_at, output_metadata: metadata,
  error_status: ok ? null : 'OUTPUT_RETRIEVAL_FAILED',
  errors: ok ? [] : [{ field: 'ltx_job.result', message: 'Job completed but no HTTPS video URL was found. Keys: ' + Object.keys(result).join(', ') }],
} }];

// Builds archive_ctx from the captured LTX output, then the shared Cloudinary preparation logic runs.
const __c = $('13 — Capture Completed Output').first().json;
const __ctx = { ...__c, archive_ctx: { shot_id: __c.manifest.shot_id, version: __c.manifest.version, generation_key: __c.manifest.generation_key, season_id: __c.manifest.season_id, episode_id: __c.manifest.episode_id, scene_id: __c.manifest.scene_id, generation_type: __c.manifest.generation_type, ltx_job_id: __c.submission.ltx_job_id, source_url: __c.output_url, force_regenerate: __c.manifest.force_regenerate === true, test: __c.manifest.episode_id === 'TEST' } };
const __ARC_INPUT = __ctx;
// Prepare Archive Request — shared by the pipeline (13A2) and the archive-repair path (X05).
// Input: $json.archive_ctx = { shot_id, version, generation_key, season_id, episode_id, scene_id, generation_type,
//                              ltx_job_id, source_url, force_regenerate, test }
// Deterministic Cloudinary identity. Every version is a separate, never-overwritten asset.
const c = (typeof __ARC_INPUT !== 'undefined') ? __ARC_INPUT : $input.first().json;
const a = c.archive_ctx;
const pad3 = (n) => String(n).padStart(3, '0');
const num = (s, prefix) => { const m = String(s || '').match(new RegExp('^' + prefix + '(\\d+)$', 'i')); return m ? m[1].padStart(2, '0') : String(s || 'x').toLowerCase().replace(/[^a-z0-9]+/g, '-'); };
const root = a.test ? 'the-sumerian/_pipeline-tests' : 'the-sumerian';
const folder = [root, 'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'), a.shot_id, 'v' + pad3(a.version)].join('/');
let asset = `${a.shot_id}_v${pad3(a.version)}`;
// An exceptional force_regenerate rerun gets its own asset so the earlier archived output is never replaced.
if (a.force_regenerate && a.ltx_job_id) asset += '_rerun-' + String(a.ltx_job_id).replace(/[^A-Za-z0-9]/g, '').slice(0, 8);
const public_id = `${folder}/${asset}`;
const esc = (v) => String(v == null ? '' : v).replace(/([=|\\])/g, '\\$1');
const context = [
  ['shot_id', a.shot_id], ['version', a.version], ['generation_key', a.generation_key], ['ltx_job_id', a.ltx_job_id],
  ['generation_type', a.generation_type], ['project', 'THE SUMERIAN'], ['pipeline', 'LTX PRODUCTION PIPELINE v1.1'],
].map(([k, v]) => `${k}=${esc(v)}`).join('|');
const tags = ['the-sumerian', a.shot_id, `${a.shot_id}_v${pad3(a.version)}`, 'v' + pad3(a.version),
  'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'),
  String(a.generation_type || '').toLowerCase().replace(/_/g, '-'), 'ltx', a.test ? 'pipeline-test' : 'production'].filter(Boolean).join(',');

return [{ json: { ...c, archive: {
  provider: 'CLOUDINARY', attempt: 0, max_attempts: 3, retry_wait_seconds: 10,
  expected_public_id: public_id, asset_folder: folder,
  params: { file: a.source_url, public_id, asset_folder: folder, overwrite: 'false', tags, context },
  history: [],
} } }];

// Count Archive Attempt — loop head of the bounded archive retry (max 3 Cloudinary attempts; never an LTX call).
const c = $input.first().json;
return [{ json: { ...c, archive: { ...c.archive, attempt: (c.archive.attempt || 0) + 1, attempt_started_at: new Date().toISOString() } } }];

// Verify Archive Result — classifies the Cloudinary upload response.
// ARCHIVED: 200 + https secure_url + expected public_id. RETRY: clearly transient (network, timeout, 429/420, 5xx) and attempts left.
// FAILED: anything else, or attempts exhausted. Never triggers an LTX generation.
const st = $('13A3 — Count Archive Attempt').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { /* keep text */ } }
const a = st.archive;
const now = new Date().toISOString();
const errMsg = b && b.error ? (b.error.message || JSON.stringify(b.error)) : (r.error ? (r.error.message || String(r.error)) : null);
const clip = (s) => String(s == null ? '' : s).replace(/(api_key|api_secret|signature)=[^&\s]+/gi, '$1=[redacted]').slice(0, 500);

let decision, detail = null, result = null;
if (status === 200 && b && typeof b.secure_url === 'string' && b.secure_url.startsWith('https://')) {
  if (b.public_id !== a.expected_public_id) {
    decision = 'FAILED'; detail = `Cloudinary stored public_id "${b.public_id}" instead of "${a.expected_public_id}".`;
  } else {
    decision = 'ARCHIVED';
    result = { archive_url: b.secure_url, archive_public_id: b.public_id, archive_asset_id: b.asset_id || '', archive_version: b.version || null,
      resource_type: b.resource_type || null, format: b.format || null, bytes: b.bytes || null, duration: b.duration || null,
      width: b.width || null, height: b.height || null, existing: b.existing === true, created_at: b.created_at || null, asset_folder: b.asset_folder || a.asset_folder,
      tags: Array.isArray(b.tags) ? b.tags : [], context: b.context && b.context.custom ? b.context.custom : (b.context || null) };
  }
} else {
  const transient = status === null || status === 408 || status === 420 || status === 429 || (status >= 500 && status <= 599);
  detail = `Cloudinary ${status === null ? 'no response (network/timeout)' : 'HTTP ' + status}${errMsg ? ': ' + clip(errMsg) : ''}`;
  decision = transient && a.attempt < a.max_attempts ? 'RETRY' : 'FAILED';
  if (decision === 'FAILED' && transient) detail += ` (gave up after ${a.attempt} attempts)`;
}

const history = [...(a.history || []), { attempt: a.attempt, at: now, http_status: status, decision, detail }];
return [{ json: { ...st, archive: { ...a, history, decision, detail, result, finished_at: decision === 'RETRY' ? null : now } } }];

// The clip was generated (and paid for) but could not be archived. No new LTX render is triggered.
const c = $('13C — Verify Archive Result').first().json;
return [{ json: { result: 'ARCHIVE_FAILED', error_status: 'OUTPUT_ARCHIVE_FAILED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'ARCHIVE_FAILED', source_output_url: c.output_url, archive_provider: 'CLOUDINARY', archive_attempts: c.archive.attempt, archive_history: c.archive.history, next_step: 'Repair the archive with the Archive Repair form (or POST /webhook/sumerian/archive-retry) while the temporary LTX URL is still valid. Do not regenerate.' } }];

// Final structured result (execution output; also persisted in the Production Library). Prefer archive_url.
const c = $('13C — Verify Archive Result').first().json;
const r = c.archive.result;
return [{ json: { result: 'REVIEW_REQUIRED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, generation_type: c.manifest.generation_type, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'REVIEW_REQUIRED', archive_url: r.archive_url, archive_provider: 'CLOUDINARY', archive_public_id: r.archive_public_id, archive_asset_id: r.archive_asset_id, source_output_url: c.output_url, estimated_cost_usd: c.ltx.estimated_cost_usd, submitted_at: c.submission.submitted_at, completed_at: c.completed_at, archived_at: c.archive.finished_at, metadata: c.output_metadata, next_step: 'Human review required (Shot Review form): APPROVE / REJECT / REQUEST_REVISION. Review the archive_url.' } }];

// ERROR — Handle Failure
// Single structured error shape for every failure path. Never includes credentials.
const j = $input.first().json || {};
const m = j.manifest || null;
const HTTP = {
  VALIDATION_ERROR: 400, MISSING_REFERENCE_ASSET: 422, NOT_AUTHORIZED: 403, COST_LIMIT_EXCEEDED: 402,
  DUPLICATE_GENERATION: 409, LTX_AUTH_ERROR: 502, LTX_RATE_LIMIT: 429, LTX_REQUEST_ERROR: 502,
  LTX_JOB_FAILED: 502, LTX_JOB_TIMEOUT: 504, OUTPUT_RETRIEVAL_FAILED: 502, UNKNOWN_ERROR: 500,
};
let error_status = j.error_status || (j.decision === 'UNSUPPORTED' ? 'VALIDATION_ERROR' : 'UNKNOWN_ERROR');
if (!HTTP[error_status]) error_status = 'UNKNOWN_ERROR';
const scrub = (s) => String(s).replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer [redacted]').replace(/(api[_-]?key|token|secret|password)["']?\s*[:=]\s*["']?[^"',\s}]+/gi, '$1=[redacted]');
const errors = (j.errors || []).map((e) => ({ field: e.field, message: scrub(e.message) }));
const shot_id = (m && m.shot_id) || (j.manifest && j.manifest.shot_id) || null;
const version = m ? m.version : null;
const generation_key = m && m.generation_key ? m.generation_key : null;
const now = new Date().toISOString();

const response_body = {
  result: 'ERROR', error_status, shot_id, version, generation_key,
  errors, warnings: j.warnings || [],
  paid_generation_submitted: !!(j.submission && (j.submission.accepted || j.submission.ambiguous)),
  ltx_job_id: j.submission ? j.submission.ltx_job_id : null,
  existing_record: error_status === 'DUPLICATE_GENERATION' && j.existing_record ? {
    generation_status: j.existing_record.generation_status, approval_status: j.existing_record.approval_status,
    ltx_job_id: j.existing_record.ltx_job_id || null, output_url: j.existing_record.output_url || null,
    submitted_at: j.existing_record.submitted_at || null, completed_at: j.existing_record.completed_at || null,
  } : null,
  timestamp: now,
};
return [{ json: {
  http_status: HTTP[error_status],
  response_body,
  // Only overwrite the library row when THIS execution created the reservation (never for duplicates/validation).
  record_update: j.has_reservation && generation_key ? {
    generation_key, generation_status: 'FAILED', approval_status: 'FAILED', error_status,
    error_detail: scrub(errors.map((e) => e.message).join(' | ')).slice(0, 2000),
    ltx_job_id: (j.submission && j.submission.ltx_job_id) || '',
    last_checked_at: j.poll ? j.poll.last_checked_at || now : now,
    poll_attempts: j.poll ? j.poll.attempts || 0 : 0,
  } : null,
  already_responded: j.already_responded === true,
} }];

// 01C — Extract Manifest Payload (v1.1: webhook-only entry)
// Human submissions arrive from THE SUMERIAN — PRODUCTION FORMS v1.1, which forwards the pasted text
// as a text/plain body. API callers send application/json. Both land in $json.body.
// Swapping the entry for a direct API later only requires producing { manifest } here.
const input = $input.first().json;
const receivedAt = new Date().toISOString();
const source = (input.headers && input.headers['x-sumerian-source']) || 'webhook';
let raw = input.body !== undefined ? input.body : input;

// Accept { "manifest": {...} } wrappers.
if (raw && typeof raw === 'object' && !Array.isArray(raw) && raw.manifest !== undefined && raw.shot_id === undefined) {
  raw = raw.manifest;
}

let manifest = null;
let parseError = null;
if (typeof raw === 'string') {
  const text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    manifest = JSON.parse(text);
  } catch (e) {
    parseError = 'Body is not valid JSON: ' + e.message;
  }
} else {
  manifest = raw;
}

if (!parseError && (manifest === null || typeof manifest !== 'object' || Array.isArray(manifest))) {
  parseError = 'Manifest must be a single JSON object (one shot per submission).';
}
if (!parseError && Object.keys(manifest).length === 0) {
  parseError = 'Manifest is empty. Send the shot manifest as the JSON request body.';
}

return [{ json: { source: String(source).slice(0, 40), received_at: receivedAt, parse_error: parseError, manifest: parseError ? null : manifest } }];

// 02 — Validate Required Fields
// Produces { valid, error_status, errors[], warnings[] } alongside the untouched manifest.
const inp = $input.first().json;
const out = { ...inp, valid: false, error_status: null, errors: [], warnings: [] };

if (inp.parse_error) {
  out.error_status = 'VALIDATION_ERROR';
  out.errors.push({ field: '$body', message: inp.parse_error });
  return [{ json: out }];
}

const m = inp.manifest;
const err = (field, message) => out.errors.push({ field, message });
const isStr = (v) => typeof v === 'string' && v.trim().length > 0;

const REQUIRED = ['project_id', 'episode_id', 'scene_id', 'shot_id', 'version', 'generation_type',
  'shot_description', 'duration_seconds', 'generation_authorized'];
for (const f of REQUIRED) {
  if (m[f] === undefined || m[f] === null || (typeof m[f] === 'string' && m[f].trim() === '')) {
    err(f, 'Required field is missing or empty.');
  }
}

// Permanent shot identifier: PROJECT-SEASON-EPISODE-SCENE-SHOT, e.g. SUM-S01-E01-SC01-SH001
const SHOT_RE = /^([A-Z0-9]{2,10})-(S\d{2})-([A-Z0-9]{2,10})-(SC\d{2,3})-(SH\d{3,4})$/;
if (isStr(m.shot_id)) {
  const mm = m.shot_id.match(SHOT_RE);
  if (!mm) {
    err('shot_id', 'shot_id must match PROJECT-SXX-EPISODE-SCXX-SHXXX (e.g. SUM-S01-E01-SC01-SH001). Do not add version suffixes to shot_id.');
  } else {
    const [, p, s, e, sc] = mm;
    if (isStr(m.project_id) && m.project_id !== p) err('shot_id', `shot_id project segment "${p}" does not match project_id "${m.project_id}".`);
    if (isStr(m.season_id) && m.season_id !== s) err('shot_id', `shot_id season segment "${s}" does not match season_id "${m.season_id}".`);
    if (isStr(m.episode_id) && m.episode_id !== e) err('shot_id', `shot_id episode segment "${e}" does not match episode_id "${m.episode_id}".`);
    if (isStr(m.scene_id) && m.scene_id !== sc) err('shot_id', `shot_id scene segment "${sc}" does not match scene_id "${m.scene_id}".`);
  }
}

if (m.version !== undefined && m.version !== null && !(Number.isInteger(m.version) && m.version >= 1)) {
  err('version', 'version must be a positive integer (1, 2, 3 ...). Versions increment; shot_id never changes.');
}

if (m.generation_authorized !== undefined && typeof m.generation_authorized !== 'boolean') {
  err('generation_authorized', 'generation_authorized must be the boolean true or false (not a string).');
}

// force_regenerate is an EXCEPTIONAL recovery switch (v1.1 policy). Normal creative iteration = version + 1.
if (m.force_regenerate !== undefined && m.force_regenerate !== null && typeof m.force_regenerate !== 'boolean') {
  err('force_regenerate', 'force_regenerate must be boolean true/false.');
}
if (m.force_regenerate === true) {
  if (!(typeof m.force_regenerate_reason === 'string' && m.force_regenerate_reason.trim().length >= 10)) {
    err('force_regenerate_reason', 'force_regenerate is for exceptional recovery only (terminal LTX failure, failed technical submission, infrastructure failure with no valid output, or a deliberate operator rerun). Provide force_regenerate_reason (10+ characters). For creative changes, keep shot_id and increment version instead.');
  } else {
    out.warnings.push('force_regenerate=true: EXCEPTIONAL rerun of the same shot_id+version. Reason recorded: ' + m.force_regenerate_reason.trim().slice(0, 200));
  }
}

const TYPES = ['IMAGE_TO_VIDEO', 'TEXT_TO_VIDEO'];
if (isStr(m.generation_type)) {
  if (m.generation_type === 'AUDIO_TO_VIDEO') err('generation_type', 'AUDIO_TO_VIDEO is reserved for a later version and is not enabled in pipeline v1.');
  else if (!TYPES.includes(m.generation_type)) err('generation_type', `generation_type must be one of ${TYPES.join(', ')}.`);
}

if (m.duration_seconds !== undefined && m.duration_seconds !== null) {
  if (typeof m.duration_seconds !== 'number' || !isFinite(m.duration_seconds) || m.duration_seconds <= 0) err('duration_seconds', 'duration_seconds must be a positive number.');
  else if (m.duration_seconds > 20) err('duration_seconds', 'duration_seconds exceeds the LTX maximum of 20 seconds per clip.');
}

if (m.aspect_ratio !== undefined && m.aspect_ratio !== null && !['16:9', '9:16'].includes(m.aspect_ratio)) {
  err('aspect_ratio', 'LTX currently supports 16:9 (landscape) and 9:16 (portrait) only.');
}
if (m.quality_mode !== undefined && m.quality_mode !== null && !['DRAFT', 'STANDARD', 'FINAL'].includes(m.quality_mode)) {
  err('quality_mode', 'quality_mode must be DRAFT, STANDARD or FINAL.');
}
if (m.max_generation_cost !== undefined && m.max_generation_cost !== null && !(typeof m.max_generation_cost === 'number' && m.max_generation_cost >= 0)) {
  err('max_generation_cost', 'max_generation_cost must be null or a non-negative number (USD).');
}
for (const f of ['characters', 'negative_constraints', 'reference_assets']) {
  if (m[f] !== undefined && m[f] !== null && !Array.isArray(m[f])) err(f, `${f} must be an array.`);
}
if (m.camera !== undefined && m.camera !== null && (typeof m.camera !== 'object' || Array.isArray(m.camera))) err('camera', 'camera must be an object.');

// Reference assets: URL must be something LTX accepts (HTTPS URL, LTX upload URI, or image data URI).
const ASSET_TYPES = ['FIRST_FRAME', 'STORYBOARD_FRAME', 'CHARACTER_REFERENCE', 'CHARACTER_MODEL_SHEET', 'ENVIRONMENT_REFERENCE',
  'PROP_REFERENCE', 'VEHICLE_REFERENCE', 'STYLE_REFERENCE', 'WEAPON_REFERENCE'];
const validImageUri = (u) => isStr(u) && (
  /^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(\/|$|\?)/i.test(u) ||
  /^ltx:\/\/uploads\/[A-Za-z0-9_-]+/.test(u) ||
  /^data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+$/.test(u));
const assets = Array.isArray(m.reference_assets) ? m.reference_assets : [];
assets.forEach((a, i) => {
  if (!a || typeof a !== 'object') return err(`reference_assets[${i}]`, 'Each reference asset must be an object.');
  if (isStr(a.asset_type) && !ASSET_TYPES.includes(a.asset_type)) out.warnings.push(`reference_assets[${i}].asset_type "${a.asset_type}" is not a known type.`);
  if (isStr(a.url) && !validImageUri(a.url)) err(`reference_assets[${i}].url`, 'URL must be public HTTPS (domain, no redirects), ltx://uploads/..., or a data:image/(png|jpeg|webp);base64 URI.');
  if (isStr(a.url) && a.url.startsWith('data:') && a.url.length > 7 * 1024 * 1024) err(`reference_assets[${i}].url`, 'Data URI exceeds the LTX 7 MB limit; host the image over HTTPS instead.');
});

let missingRef = false;
if (m.generation_type === 'IMAGE_TO_VIDEO') {
  // LTX image-to-video uses image_uri as the literal FIRST FRAME of the clip.
  const FRAME_PRIORITY = ['FIRST_FRAME', 'STORYBOARD_FRAME', 'CHARACTER_REFERENCE', 'CHARACTER_MODEL_SHEET', 'ENVIRONMENT_REFERENCE'];
  const usable = assets.filter((a) => a && validImageUri(a.url) && a.approved !== false);
  const pick = FRAME_PRIORITY.map((t) => usable.find((a) => a.asset_type === t)).find(Boolean);
  if (!pick) {
    missingRef = true;
    err('reference_assets', 'IMAGE_TO_VIDEO requires at least one approved reference asset (FIRST_FRAME / STORYBOARD_FRAME preferred) with a valid image URL.');
  } else {
    if (!['FIRST_FRAME', 'STORYBOARD_FRAME'].includes(pick.asset_type)) {
      out.warnings.push(`LTX uses the image as the literal first frame. Using ${pick.asset_type} "${pick.asset_id || ''}"; a composed FIRST_FRAME/STORYBOARD_FRAME gives better shot control.`);
    }
    if (pick.approved !== true) out.warnings.push(`Reference "${pick.asset_id || pick.url.slice(0, 40)}" is not marked approved:true. Only approved assets should define character identity.`);
  }
}

out.valid = out.errors.length === 0;
if (!out.valid) out.error_status = (missingRef && out.errors.length === 1) ? 'MISSING_REFERENCE_ASSET' : (missingRef ? 'MISSING_REFERENCE_ASSET' : 'VALIDATION_ERROR');
return [{ json: out }];

// 03 — Normalize Manifest
// Translates the INTERNAL Sumerian schema into a normalized manifest + an LTX request plan.
// LTX facts below verified against docs.ltx.io on 2026-09-23 (v2 async API). Update LTX_SPEC if LTX changes.
const inp = $input.first().json;
const m = inp.manifest;
const warnings = [...(inp.warnings || [])];
const s = (v) => (typeof v === 'string' ? v.trim() : '');
const arr = (v) => (Array.isArray(v) ? v : []);

const LTX_SPEC = {
  api_base: 'https://api.ltx.io/v2',
  endpoints: { IMAGE_TO_VIDEO: 'image-to-video', TEXT_TO_VIDEO: 'text-to-video' },
  camera_motion: ['dolly_in', 'dolly_out', 'dolly_left', 'dolly_right', 'jib_up', 'jib_down', 'static', 'focus_shift'],
  resolutions: { '16:9': { '720p': '1280x720', '1080p': '1920x1080', '1440p': '2560x1440', '4k': '3840x2160' },
                 '9:16': { '720p': '720x1280', '1080p': '1080x1920', '1440p': '1440x2560', '4k': '2160x3840' } },
  // USD per output second (text/image-to-video), from docs.ltx.io/pricing
  price_per_second: {
    'ltx-2-3-fast': { '720p': 0.03, '1080p': 0.06, '1440p': 0.12, '4k': 0.24 },
    'ltx-2-3-pro':  { '720p': 0.04, '1080p': 0.08, '1440p': 0.16, '4k': 0.32 },
    'ltx-2-5-fast': { '720p': 0.09, '1080p': 0.13, '1440p': 0.19, '4k': 0.30 },
    'ltx-2-5-pro':  { '720p': 0.12, '1080p': 0.17, '1440p': 0.25, '4k': 0.39 },
  },
  pricing_verified: '2026-09-23', // re-verified against docs.ltx.io/pricing for v1.1 (unchanged)
};
// quality_mode → LTX model/tier (v1.1).
// DRAFT = exploration only (choreography, camera, motion, continuity, character drift, prompt and pipeline tests). Not final output.
const QUALITY = {
  DRAFT:    { model: 'ltx-2-3-fast', tier: '720p' },
  STANDARD: { model: 'ltx-2-3-pro',  tier: '1080p' },
  FINAL:    { model: 'ltx-2-5-pro',  tier: '1080p' },
};

const quality_mode = m.quality_mode || 'DRAFT';
const aspect_ratio = m.aspect_ratio || '16:9';
const q = QUALITY[quality_mode];
const model = (typeof m.ltx_model === 'string' && LTX_SPEC.price_per_second[m.ltx_model]) ? m.ltx_model : q.model;
let tier = (typeof m.ltx_resolution_tier === 'string' && ['720p', '1080p', '1440p', '4k'].includes(m.ltx_resolution_tier.toLowerCase())) ? m.ltx_resolution_tier.toLowerCase() : q.tier;
const fps = [24, 25, 48, 50].includes(m.fps) ? m.fps : 24;
const resolution = LTX_SPEC.resolutions[aspect_ratio][tier];

// Allowed durations: even seconds 6..10, or 6..20 for *-fast at <=1080p and 24/25 fps.
const maxDur = (model.endsWith('-fast') && ['720p', '1080p'].includes(tier) && fps <= 25) ? 20 : 10;
const requested = m.duration_seconds;
let duration = Math.max(6, Math.ceil(requested / 2) * 2);
let duration_error = null;
if (duration > maxDur) duration_error = `duration_seconds ${requested} exceeds ${maxDur}s for ${model} at ${tier}/${fps}fps.`;
if (duration !== requested) warnings.push(`duration_seconds ${requested} normalized to ${duration}s (LTX accepts even durations from 6s; billing is per output second).`);

// Camera: map to an LTX camera_motion preset only when it matches exactly; otherwise describe it in the prompt.
const cam = (m.camera && typeof m.camera === 'object') ? m.camera : {};
const movementKey = s(cam.movement).toLowerCase().replace(/[\s-]+/g, '_');
const camera_motion = LTX_SPEC.camera_motion.includes(movementKey) ? movementKey : null;

// Reference selection (LTX image_uri = literal first frame).
const assets = arr(m.reference_assets).filter((a) => a && typeof a === 'object').map((a) => ({
  asset_id: s(a.asset_id), asset_type: s(a.asset_type) || 'CHARACTER_REFERENCE', url: s(a.url), approved: a.approved === true,
}));
const FRAME_PRIORITY = ['FIRST_FRAME', 'STORYBOARD_FRAME', 'CHARACTER_REFERENCE', 'CHARACTER_MODEL_SHEET', 'ENVIRONMENT_REFERENCE'];
const firstFrame = m.generation_type === 'IMAGE_TO_VIDEO'
  ? FRAME_PRIORITY.map((t) => assets.find((a) => a.asset_type === t && a.url)).find(Boolean) || null
  : null;

// Prompt assembly, following the LTX prompting guide order:
// shot establishment → scene/lighting → action → character → camera → audio. Only shot-relevant context is included.
const sentence = (t) => { t = s(t); return t ? (/[.!?]$/.test(t) ? t : t + '.') : ''; };
const camBits = [s(cam.framing), s(cam.angle) && `${s(cam.angle)} angle`, s(cam.lens_intent)].filter(Boolean).join(', ');
const chars = arr(m.characters).map((c) => (typeof c === 'string' ? c : (c && (c.name || c.character_id)) || '')).filter(Boolean);
const parts = [
  sentence(camBits ? `${camBits}. ${s(m.shot_description)}` : m.shot_description),
  sentence([s(m.location), s(m.environment)].filter(Boolean).join(' — ')),
  sentence(m.lighting),
  sentence(m.character_action),
  sentence(s(m.character_emotion) && `Emotion: ${s(m.character_emotion)}`),
  sentence(s(cam.movement) && `Camera: ${s(cam.movement)}`),
  sentence(m.visual_style),
  sentence(m.continuity_notes && m.generation_type === 'IMAGE_TO_VIDEO' ? `Single continuous take, consistent with the opening frame. ${s(m.continuity_notes)}` : m.continuity_notes),
  s(m.dialogue) ? `Dialogue: "${s(m.dialogue).replace(/^"|"$/g, '')}".` : '',
  sentence(s(m.sound_requirements) && `Audio: ${s(m.sound_requirements)}`),
  // LTX has no negative-prompt field; constraints are phrased as an exclusion sentence.
  arr(m.negative_constraints).length ? `Keep the frame free of: ${arr(m.negative_constraints).join(', ')}.` : '',
].filter(Boolean);
const prompt = parts.join(' ').replace(/\s+/g, ' ').trim();

const generate_audio = typeof m.generate_audio === 'boolean' ? m.generate_audio : !/^(none|no audio|silent)$/i.test(s(m.sound_requirements));
const price = LTX_SPEC.price_per_second[model][tier];
const estimated_cost_usd = Math.round(price * duration * 100) / 100;

const version = m.version;
const normalized = {
  project_id: s(m.project_id), season_id: s(m.season_id) || m.shot_id.split('-')[1], episode_id: s(m.episode_id),
  scene_id: s(m.scene_id), shot_id: m.shot_id, version,
  generation_key: `${m.shot_id}::v${version}`,
  generation_authorized: m.generation_authorized === true,
  force_regenerate: m.force_regenerate === true,
  force_regenerate_reason: m.force_regenerate === true ? s(m.force_regenerate_reason).slice(0, 500) : '',
  generation_type: m.generation_type,
  story_purpose: s(m.story_purpose), shot_description: s(m.shot_description), characters: arr(m.characters),
  location: s(m.location), reference_assets: assets, character_action: s(m.character_action), character_emotion: s(m.character_emotion),
  camera: { framing: s(cam.framing), angle: s(cam.angle), movement: s(cam.movement), lens_intent: s(cam.lens_intent) },
  environment: s(m.environment), lighting: s(m.lighting), visual_style: s(m.visual_style), continuity_notes: s(m.continuity_notes),
  negative_constraints: arr(m.negative_constraints), dialogue: s(m.dialogue), sound_requirements: s(m.sound_requirements),
  duration_seconds_requested: requested, duration_seconds: duration, aspect_ratio, quality_mode,
  approval_status: 'PREPRODUCTION', max_generation_cost: (typeof m.max_generation_cost === 'number') ? m.max_generation_cost : null,
  revision_of_version: Number.isInteger(m.revision_of_version) ? m.revision_of_version : null,
  revision_notes: s(m.revision_notes),
};

const ltx = {
  endpoint: LTX_SPEC.endpoints[m.generation_type],
  submit_url: `${LTX_SPEC.api_base}/${LTX_SPEC.endpoints[m.generation_type]}`,
  model, resolution, resolution_tier: tier, fps, duration, generate_audio, camera_motion,
  image_uri: firstFrame ? firstFrame.url : null,
  first_frame_asset_id: firstFrame ? firstFrame.asset_id : null,
  prompt,
  estimated_cost_usd, price_per_second_usd: price, pricing_verified: LTX_SPEC.pricing_verified,
};

return [{ json: {
  source: inp.source, received_at: inp.received_at,
  normalize_error: duration_error, error_status: duration_error ? 'VALIDATION_ERROR' : null,
  errors: duration_error ? [{ field: 'duration_seconds', message: duration_error }] : [],
  warnings, manifest: normalized, ltx,
} }];

// 04 — Check Generation Authorization
// Paid generation requires generation_authorized === true AND (if set) estimated cost <= max_generation_cost.
const ctx = $('03 — Normalize Manifest').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.generation_key);
const existing = rows.length ? rows[0] : null;
const m = ctx.manifest;
const ltx = ctx.ltx;

let gate = 'AUTHORIZED';
let reason = 'generation_authorized is true and the cost check passed.';
if (m.generation_authorized !== true) {
  gate = 'READY_FOR_APPROVAL';
  reason = 'generation_authorized is false. No paid LTX request was made. Resubmit the same manifest with "generation_authorized": true to generate.';
} else if (m.max_generation_cost !== null && ltx.estimated_cost_usd > m.max_generation_cost) {
  gate = 'COST_LIMIT_EXCEEDED';
  reason = `Estimated cost $${ltx.estimated_cost_usd} (${ltx.duration}s × $${ltx.price_per_second_usd}/s, ${ltx.model} @ ${ltx.resolution_tier}) exceeds max_generation_cost $${m.max_generation_cost}.`;
}

return [{ json: {
  ...ctx,
  gate, gate_reason: reason,
  existing_record: existing,
  error_status: gate === 'COST_LIMIT_EXCEEDED' ? 'COST_LIMIT_EXCEEDED' : null,
  errors: gate === 'COST_LIMIT_EXCEEDED' ? [{ field: 'max_generation_cost', message: reason }] : [],
} }];

// 04B — Stage READY_FOR_APPROVAL
// Records the normalized shot in the Production Library without spending credits.
// Never overwrites a record that already has an LTX job or a review decision.
const ctx = $input.first().json;
const m = ctx.manifest;
const ex = ctx.existing_record;
const now = new Date().toISOString();
const PROTECTED = ['SUBMITTING', 'GENERATING', 'COMPLETED', 'FAILED'];
const canWrite = !ex || (!ex.ltx_job_id && !PROTECTED.includes(ex.generation_status));

const record = {
  generation_key: m.generation_key, project_id: m.project_id, season_id: m.season_id, episode_id: m.episode_id,
  scene_id: m.scene_id, shot_id: m.shot_id, version: m.version, generation_type: m.generation_type,
  generation_status: 'NOT_SUBMITTED', approval_status: 'READY_FOR_APPROVAL',
  ltx_endpoint: ctx.ltx.endpoint, ltx_model: ctx.ltx.model, ltx_resolution: ctx.ltx.resolution,
  duration_seconds: ctx.ltx.duration, estimated_cost_usd: ctx.ltx.estimated_cost_usd,
  submitted_prompt: ctx.ltx.prompt, reference_assets: JSON.stringify(m.reference_assets),
  first_frame_asset_id: ctx.ltx.first_frame_asset_id || '',
  manifest_json: JSON.stringify(m), metadata_json: JSON.stringify({ staged_at: now, source: ctx.source, warnings: ctx.warnings }),
};

const response = {
  result: 'READY_FOR_APPROVAL',
  shot_id: m.shot_id, version: m.version, generation_key: m.generation_key,
  message: ctx.gate_reason,
  paid_generation_submitted: false,
  production_library: canWrite ? 'Recorded as READY_FOR_APPROVAL.' : `Existing record kept unchanged (status ${ex.generation_status}/${ex.approval_status}).`,
  existing_record: canWrite ? null : { generation_status: ex.generation_status, approval_status: ex.approval_status, ltx_job_id: ex.ltx_job_id || null, output_url: ex.output_url || null },
  ltx_plan: { endpoint: ctx.ltx.endpoint, model: ctx.ltx.model, resolution: ctx.ltx.resolution, duration_seconds: ctx.ltx.duration,
    fps: ctx.ltx.fps, generate_audio: ctx.ltx.generate_audio, camera_motion: ctx.ltx.camera_motion,
    first_frame_asset_id: ctx.ltx.first_frame_asset_id, estimated_cost_usd: ctx.ltx.estimated_cost_usd,
    pricing_source: `docs.ltx.io/pricing (verified ${ctx.ltx.pricing_verified})`, prompt: ctx.ltx.prompt },
  warnings: ctx.warnings,
  normalized_manifest: m,
};
return [{ json: { should_write: canWrite, record, response } }];

// 05 — Check Duplicate Shot Version (v1.1)
// A generation attempt = SHOT_ID + VERSION (generation_key). SHOT_ID is permanent; creative revisions increment VERSION.
// force_regenerate is EXCEPTIONAL: it can only re-open an attempt whose previous LTX job terminally FAILED.
// It can never re-render a COMPLETED (or archive-failed) clip: that output already exists and was paid for.
const ctx = $input.first().json;
const m = ctx.manifest;
const ex = ctx.existing_record;
const BLOCKING_GEN = ['SUBMITTING', 'GENERATING', 'COMPLETED'];
const BLOCKING_APPROVAL = ['GENERATING', 'ARCHIVING', 'ARCHIVE_FAILED', 'REVIEW_REQUIRED', 'APPROVED', 'REVISION_REQUESTED', 'REJECTED'];
const warnings = [...(ctx.warnings || [])];

let duplicate = false;
let reason = null;
if (ex) {
  const active = BLOCKING_GEN.includes(ex.generation_status) || BLOCKING_APPROVAL.includes(ex.approval_status);
  const failedWithJob = ex.generation_status === 'FAILED' && !!ex.ltx_job_id;
  if (active) {
    duplicate = true;
    if (['ARCHIVING', 'ARCHIVE_FAILED'].includes(ex.approval_status)) {
      reason = `${m.generation_key} was generated successfully but is not archived yet (${ex.approval_status}). Do NOT regenerate: repair the archive via the archive-retry endpoint / Archive Repair form. The temporary LTX URL is kept in source_output_url.`;
    } else {
      reason = `${m.generation_key} already has generation_status=${ex.generation_status}, approval_status=${ex.approval_status}${ex.ltx_job_id ? ', ltx_job_id=' + ex.ltx_job_id : ''}. For a creative change keep shot_id and submit version ${Number(m.version) + 1}.`;
    }
    if (m.force_regenerate) reason += ' force_regenerate does not apply: it only re-opens attempts whose previous LTX job FAILED.';
  } else if (failedWithJob && !m.force_regenerate) {
    duplicate = true;
    reason = `${m.generation_key} previously FAILED after an LTX job was created (${ex.ltx_job_id}; ${ex.error_status}). Check the LTX console. Then either submit version ${Number(m.version) + 1}, or (exceptional recovery only) resend with "force_regenerate": true and a force_regenerate_reason.`;
  } else if (m.force_regenerate) {
    warnings.push(`EXCEPTIONAL: force_regenerate re-opening ${m.generation_key} (previous status ${ex.generation_status}/${ex.error_status || 'n/a'}).`);
  }
} else if (m.force_regenerate) {
  warnings.push('force_regenerate was set but no previous attempt exists; it has no effect.');
}

const now = new Date().toISOString();
return [{ json: {
  ...ctx,
  warnings,
  duplicate,
  error_status: duplicate ? 'DUPLICATE_GENERATION' : null,
  errors: duplicate ? [{ field: 'shot_id+version', message: reason }] : [],
  reservation: duplicate ? null : {
    generation_key: m.generation_key, project_id: m.project_id, season_id: m.season_id, episode_id: m.episode_id,
    scene_id: m.scene_id, shot_id: m.shot_id, version: m.version, generation_type: m.generation_type,
    generation_status: 'SUBMITTING', approval_status: 'AUTHORIZED',
    ltx_job_id: '', ltx_endpoint: ctx.ltx.endpoint, ltx_model: ctx.ltx.model, ltx_resolution: ctx.ltx.resolution,
    duration_seconds: ctx.ltx.duration, estimated_cost_usd: ctx.ltx.estimated_cost_usd,
    submitted_prompt: ctx.ltx.prompt, reference_assets: JSON.stringify(m.reference_assets),
    first_frame_asset_id: ctx.ltx.first_frame_asset_id || '', submitted_at: now, poll_attempts: 0,
    error_status: '', error_detail: '', output_url: '', completed_at: '',
    source_output_url: '', archive_url: '', archive_provider: '', archive_asset_id: '', archive_public_id: '', archived_at: '', archive_attempts: 0,
    manifest_json: JSON.stringify(m),
    metadata_json: JSON.stringify({ authorized_at: now, source: ctx.source, warnings,
      force_regenerate: m.force_regenerate, force_regenerate_reason: m.force_regenerate_reason || null,
      previous_attempt: m.force_regenerate && ex ? { ltx_job_id: ex.ltx_job_id || null, error_status: ex.error_status || null } : null }),
  },
} }];

// Placeholder branch for AUDIO_TO_VIDEO (future). Reaching here means the router saw an unknown type.
const c = $('05 — Check Duplicate Shot Version').first().json;
return [{ json: { ...c, has_reservation: true, error_status: 'VALIDATION_ERROR', errors: [{ field: 'generation_type', message: 'No LTX route configured for ' + c.manifest.generation_type }] } }];

// 07A — Prepare Image-to-Video
// Maps the normalized manifest to POST https://api.ltx.io/v2/image-to-video (fields per docs.ltx.io).
const ctx = $('05 — Check Duplicate Shot Version').first().json;
const l = ctx.ltx;
const body = { image_uri: l.image_uri, prompt: l.prompt, model: l.model, duration: l.duration, resolution: l.resolution, fps: l.fps, generate_audio: l.generate_audio };
if (l.camera_motion) body.camera_motion = l.camera_motion;
return [{ json: { ...ctx, ltx_request: { endpoint: 'image-to-video', url: 'https://api.ltx.io/v2/image-to-video', body } } }];

// 07B — Prepare Text-to-Video
// Maps the normalized manifest to POST https://api.ltx.io/v2/text-to-video (fields per docs.ltx.io).
const ctx = $('05 — Check Duplicate Shot Version').first().json;
const l = ctx.ltx;
const body = { prompt: l.prompt, model: l.model, duration: l.duration, resolution: l.resolution, fps: l.fps, generate_audio: l.generate_audio };
if (l.camera_motion) body.camera_motion = l.camera_motion;
return [{ json: { ...ctx, ltx_request: { endpoint: 'text-to-video', url: 'https://api.ltx.io/v2/text-to-video', body } } }];

// 08A — Interpret LTX Submission
// Classifies the submit response. NEVER retries a paid submission automatically.
const ctx = $('07A — Prepare Image-to-Video').isExecuted
  ? $('07A — Prepare Image-to-Video').first().json
  : $('07B — Prepare Text-to-Video').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep text */ } }
const apiErr = body && typeof body === 'object' && body.error ? body.error : null;
const now = new Date().toISOString();
const clip = (v) => String(v == null ? '' : (typeof v === 'string' ? v : JSON.stringify(v))).slice(0, 1500);

let accepted = false, error_status = null, detail = null, ambiguous = false;
if (status === 202 || status === 200 || status === 201) {
  if (body && body.id) accepted = true;
  else { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = 'LTX returned success without a job id: ' + clip(body); }
} else if (status === 401 || status === 403) { error_status = 'LTX_AUTH_ERROR'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : 'Authentication failed. Check the "LTX VIDEO API — THE SUMERIAN" credential.'; }
else if (status === 429) { error_status = 'LTX_RATE_LIMIT'; detail = (apiErr ? `${apiErr.type}: ${apiErr.message}` : 'Rate limited') + (r.headers && r.headers['retry-after'] ? ` (Retry-After ${r.headers['retry-after']}s)` : '') + '. Not retried automatically; resubmit later.'; }
else if (status === 402) { error_status = 'LTX_REQUEST_ERROR'; detail = 'insufficient_funds_error: LTX account has insufficient credits.'; }
else if (status && status >= 400 && status < 500) { error_status = 'LTX_REQUEST_ERROR'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : `HTTP ${status}: ${clip(body)}`; }
else if (status && status >= 500) { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = `LTX HTTP ${status} on submit. The job MAY have been created; not retried to avoid a duplicate charge. ${apiErr ? apiErr.type + ': ' + apiErr.message : ''}`; }
else { error_status = 'UNKNOWN_ERROR'; ambiguous = true; detail = 'No HTTP response from LTX (network/timeout). The job MAY have been created; not retried to avoid a duplicate charge. ' + clip(r.error && (r.error.message || r.error)); }

return [{ json: {
  ...ctx,
  submission: { accepted, http_status: status, ltx_job_id: accepted ? body.id : null, ltx_created_at: accepted ? (body.created_at || null) : null, submitted_at: now, ambiguous },
  error_status, errors: error_status ? [{ field: 'ltx_submit', message: detail }] : [],
  has_reservation: true, already_responded: false,
  poll: accepted ? { attempts: 0, max_attempts: 45, interval_seconds: 20, max_elapsed_minutes: 20, transient_errors: 0, started_at: now } : null,
} }];

// 12 — Evaluate Job Status
// Bounded polling: stops after max_attempts or max_elapsed_minutes, whichever comes first.
const state = $('10 — Wait Before Poll').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep */ } }
const now = new Date();
const poll = { ...state.poll, attempts: (state.poll.attempts || 0) + 1, last_checked_at: now.toISOString(), last_http_status: status };
const elapsedMin = (now - new Date(state.poll.started_at)) / 60000;
const apiErr = body && typeof body === 'object' && body.error ? body.error : null;

let decision = 'CONTINUE', error_status = null, detail = null, job_status = body && body.status ? body.status : null;
if (status === 200 && body && body.status) {
  if (body.status === 'completed') decision = 'COMPLETED';
  else if (body.status === 'failed') { decision = 'ERROR'; error_status = 'LTX_JOB_FAILED'; detail = apiErr ? `${apiErr.type}: ${apiErr.message}` : 'LTX reported the job as failed.'; }
  else decision = 'CONTINUE'; // pending | processing
} else if (status === 401 || status === 403) { decision = 'ERROR'; error_status = 'LTX_AUTH_ERROR'; detail = 'Authentication failed while polling.'; }
else if (status === 404) { decision = 'ERROR'; error_status = 'LTX_JOB_FAILED'; detail = 'Job not found (expired or unknown id).'; }
else { // 429 / 5xx / network: transient, keep polling within limits
  poll.transient_errors = (poll.transient_errors || 0) + 1;
  if (poll.transient_errors >= 6) { decision = 'ERROR'; error_status = status === 429 ? 'LTX_RATE_LIMIT' : 'UNKNOWN_ERROR'; detail = `Polling failed ${poll.transient_errors} times (last HTTP ${status}). Job ${state.submission.ltx_job_id} may still complete; check LTX before resubmitting.`; }
}
if (decision === 'CONTINUE' && (poll.attempts >= poll.max_attempts || elapsedMin >= poll.max_elapsed_minutes)) {
  decision = 'ERROR'; error_status = 'LTX_JOB_TIMEOUT';
  detail = `Job ${state.submission.ltx_job_id} still "${job_status}" after ${poll.attempts} polls / ${elapsedMin.toFixed(1)} min. Polling stopped. Record kept; do not resubmit the same version blindly.`;
}

return [{ json: {
  ...state, poll, decision, job_status,
  job: status === 200 ? body : null,
  error_status, errors: error_status ? [{ field: 'ltx_job', message: detail }] : [],
  has_reservation: true, already_responded: true,
} }];

// 13 — Capture Completed Output
const ctx = $input.first().json;
const job = ctx.job || {};
const result = job.result || {};
const url = result.video_url || Object.values(result).find((v) => typeof v === 'string' && /^https:\/\//.test(v)) || null;
const ok = typeof url === 'string' && url.startsWith('https://');
const completed_at = job.completed_at || new Date().toISOString();
const submittedMs = new Date(ctx.submission.submitted_at).getTime();
const metadata = {
  ltx_job_id: ctx.submission.ltx_job_id, ltx_created_at: job.created_at || ctx.submission.ltx_created_at, ltx_completed_at: job.completed_at || null,
  generation_seconds: Math.round((new Date(completed_at).getTime() - submittedMs) / 1000),
  poll_attempts: ctx.poll.attempts, result_keys: Object.keys(result),
  request: ctx.ltx_request.body.image_uri && ctx.ltx_request.body.image_uri.startsWith('data:')
    ? { ...ctx.ltx_request.body, image_uri: '[data-uri omitted]' } : ctx.ltx_request.body,
  estimated_cost_usd: ctx.ltx.estimated_cost_usd, cost_basis: `${ctx.ltx.duration}s × $${ctx.ltx.price_per_second_usd}/s (docs.ltx.io/pricing, ${ctx.ltx.pricing_verified})`,
  output_url_note: 'LTX output URLs expire. Download/archive the clip promptly.',
  warnings: ctx.warnings,
};
return [{ json: {
  ...ctx, output_ok: ok, output_url: url, completed_at, output_metadata: metadata,
  error_status: ok ? null : 'OUTPUT_RETRIEVAL_FAILED',
  errors: ok ? [] : [{ field: 'ltx_job.result', message: 'Job completed but no HTTPS video URL was found. Keys: ' + Object.keys(result).join(', ') }],
} }];

// Builds archive_ctx from the captured LTX output, then the shared Cloudinary preparation logic runs.
const __c = $('13 — Capture Completed Output').first().json;
const __ctx = { ...__c, archive_ctx: { shot_id: __c.manifest.shot_id, version: __c.manifest.version, generation_key: __c.manifest.generation_key, season_id: __c.manifest.season_id, episode_id: __c.manifest.episode_id, scene_id: __c.manifest.scene_id, generation_type: __c.manifest.generation_type, ltx_job_id: __c.submission.ltx_job_id, source_url: __c.output_url, force_regenerate: __c.manifest.force_regenerate === true, test: __c.manifest.episode_id === 'TEST' } };
const __ARC_INPUT = __ctx;
// Prepare Archive Request — shared by the pipeline (13A2) and the archive-repair path (X05).
// Input: $json.archive_ctx = { shot_id, version, generation_key, season_id, episode_id, scene_id, generation_type,
//                              ltx_job_id, source_url, force_regenerate, test }
// Deterministic Cloudinary identity. Every version is a separate, never-overwritten asset.
const c = (typeof __ARC_INPUT !== 'undefined') ? __ARC_INPUT : $input.first().json;
const a = c.archive_ctx;
const pad3 = (n) => String(n).padStart(3, '0');
const num = (s, prefix) => { const m = String(s || '').match(new RegExp('^' + prefix + '(\\d+)$', 'i')); return m ? m[1].padStart(2, '0') : String(s || 'x').toLowerCase().replace(/[^a-z0-9]+/g, '-'); };
const root = a.test ? 'the-sumerian/_pipeline-tests' : 'the-sumerian';
const folder = [root, 'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'), a.shot_id, 'v' + pad3(a.version)].join('/');
let asset = `${a.shot_id}_v${pad3(a.version)}`;
// An exceptional force_regenerate rerun gets its own asset so the earlier archived output is never replaced.
if (a.force_regenerate && a.ltx_job_id) asset += '_rerun-' + String(a.ltx_job_id).replace(/[^A-Za-z0-9]/g, '').slice(0, 8);
const public_id = `${folder}/${asset}`;
const esc = (v) => String(v == null ? '' : v).replace(/([=|\\])/g, '\\$1');
const context = [
  ['shot_id', a.shot_id], ['version', a.version], ['generation_key', a.generation_key], ['ltx_job_id', a.ltx_job_id],
  ['generation_type', a.generation_type], ['project', 'THE SUMERIAN'], ['pipeline', 'LTX PRODUCTION PIPELINE v1.1'],
].map(([k, v]) => `${k}=${esc(v)}`).join('|');
const tags = ['the-sumerian', a.shot_id, `${a.shot_id}_v${pad3(a.version)}`, 'v' + pad3(a.version),
  'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'),
  String(a.generation_type || '').toLowerCase().replace(/_/g, '-'), 'ltx', a.test ? 'pipeline-test' : 'production'].filter(Boolean).join(',');

return [{ json: { ...c, archive: {
  provider: 'CLOUDINARY', attempt: 0, max_attempts: 3, retry_wait_seconds: 10,
  expected_public_id: public_id, asset_folder: folder,
  params: { file: a.source_url, public_id, asset_folder: folder, overwrite: 'false', tags, context },
  history: [],
} } }];

// Count Archive Attempt — loop head of the bounded archive retry (max 3 Cloudinary attempts; never an LTX call).
const c = $input.first().json;
return [{ json: { ...c, archive: { ...c.archive, attempt: (c.archive.attempt || 0) + 1, attempt_started_at: new Date().toISOString() } } }];

// Verify Archive Result — classifies the Cloudinary upload response.
// ARCHIVED: 200 + https secure_url + expected public_id. RETRY: clearly transient (network, timeout, 429/420, 5xx) and attempts left.
// FAILED: anything else, or attempts exhausted. Never triggers an LTX generation.
const st = $('13A3 — Count Archive Attempt').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { /* keep text */ } }
const a = st.archive;
const now = new Date().toISOString();
const errMsg = b && b.error ? (b.error.message || JSON.stringify(b.error)) : (r.error ? (r.error.message || String(r.error)) : null);
const clip = (s) => String(s == null ? '' : s).replace(/(api_key|api_secret|signature)=[^&\s]+/gi, '$1=[redacted]').slice(0, 500);

let decision, detail = null, result = null;
if (status === 200 && b && typeof b.secure_url === 'string' && b.secure_url.startsWith('https://')) {
  if (b.public_id !== a.expected_public_id) {
    decision = 'FAILED'; detail = `Cloudinary stored public_id "${b.public_id}" instead of "${a.expected_public_id}".`;
  } else {
    decision = 'ARCHIVED';
    result = { archive_url: b.secure_url, archive_public_id: b.public_id, archive_asset_id: b.asset_id || '', archive_version: b.version || null,
      resource_type: b.resource_type || null, format: b.format || null, bytes: b.bytes || null, duration: b.duration || null,
      width: b.width || null, height: b.height || null, existing: b.existing === true, created_at: b.created_at || null, asset_folder: b.asset_folder || a.asset_folder,
      tags: Array.isArray(b.tags) ? b.tags : [], context: b.context && b.context.custom ? b.context.custom : (b.context || null) };
  }
} else {
  const transient = status === null || status === 408 || status === 420 || status === 429 || (status >= 500 && status <= 599);
  detail = `Cloudinary ${status === null ? 'no response (network/timeout)' : 'HTTP ' + status}${errMsg ? ': ' + clip(errMsg) : ''}`;
  decision = transient && a.attempt < a.max_attempts ? 'RETRY' : 'FAILED';
  if (decision === 'FAILED' && transient) detail += ` (gave up after ${a.attempt} attempts)`;
}

const history = [...(a.history || []), { attempt: a.attempt, at: now, http_status: status, decision, detail }];
return [{ json: { ...st, archive: { ...a, history, decision, detail, result, finished_at: decision === 'RETRY' ? null : now } } }];

// The clip was generated (and paid for) but could not be archived. No new LTX render is triggered.
const c = $('13C — Verify Archive Result').first().json;
return [{ json: { result: 'ARCHIVE_FAILED', error_status: 'OUTPUT_ARCHIVE_FAILED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'ARCHIVE_FAILED', source_output_url: c.output_url, archive_provider: 'CLOUDINARY', archive_attempts: c.archive.attempt, archive_history: c.archive.history, next_step: 'Repair the archive with the Archive Repair form (or POST /webhook/sumerian/archive-retry) while the temporary LTX URL is still valid. Do not regenerate.' } }];

// Final structured result (execution output; also persisted in the Production Library). Prefer archive_url.
const c = $('13C — Verify Archive Result').first().json;
const r = c.archive.result;
return [{ json: { result: 'REVIEW_REQUIRED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, generation_type: c.manifest.generation_type, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'REVIEW_REQUIRED', archive_url: r.archive_url, archive_provider: 'CLOUDINARY', archive_public_id: r.archive_public_id, archive_asset_id: r.archive_asset_id, source_output_url: c.output_url, estimated_cost_usd: c.ltx.estimated_cost_usd, submitted_at: c.submission.submitted_at, completed_at: c.completed_at, archived_at: c.archive.finished_at, metadata: c.output_metadata, next_step: 'Human review required (Shot Review form): APPROVE / REJECT / REQUEST_REVISION. Review the archive_url.' } }];

// ERROR — Handle Failure
// Single structured error shape for every failure path. Never includes credentials.
const j = $input.first().json || {};
const m = j.manifest || null;
const HTTP = {
  VALIDATION_ERROR: 400, MISSING_REFERENCE_ASSET: 422, NOT_AUTHORIZED: 403, COST_LIMIT_EXCEEDED: 402,
  DUPLICATE_GENERATION: 409, LTX_AUTH_ERROR: 502, LTX_RATE_LIMIT: 429, LTX_REQUEST_ERROR: 502,
  LTX_JOB_FAILED: 502, LTX_JOB_TIMEOUT: 504, OUTPUT_RETRIEVAL_FAILED: 502, UNKNOWN_ERROR: 500,
};
let error_status = j.error_status || (j.decision === 'UNSUPPORTED' ? 'VALIDATION_ERROR' : 'UNKNOWN_ERROR');
if (!HTTP[error_status]) error_status = 'UNKNOWN_ERROR';
const scrub = (s) => String(s).replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer [redacted]').replace(/(api[_-]?key|token|secret|password)["']?\s*[:=]\s*["']?[^"',\s}]+/gi, '$1=[redacted]');
const errors = (j.errors || []).map((e) => ({ field: e.field, message: scrub(e.message) }));
const shot_id = (m && m.shot_id) || (j.manifest && j.manifest.shot_id) || null;
const version = m ? m.version : null;
const generation_key = m && m.generation_key ? m.generation_key : null;
const now = new Date().toISOString();

const response_body = {
  result: 'ERROR', error_status, shot_id, version, generation_key,
  errors, warnings: j.warnings || [],
  paid_generation_submitted: !!(j.submission && (j.submission.accepted || j.submission.ambiguous)),
  ltx_job_id: j.submission ? j.submission.ltx_job_id : null,
  existing_record: error_status === 'DUPLICATE_GENERATION' && j.existing_record ? {
    generation_status: j.existing_record.generation_status, approval_status: j.existing_record.approval_status,
    ltx_job_id: j.existing_record.ltx_job_id || null, output_url: j.existing_record.output_url || null,
    submitted_at: j.existing_record.submitted_at || null, completed_at: j.existing_record.completed_at || null,
  } : null,
  timestamp: now,
};
return [{ json: {
  http_status: HTTP[error_status],
  response_body,
  // Only overwrite the library row when THIS execution created the reservation (never for duplicates/validation).
  record_update: j.has_reservation && generation_key ? {
    generation_key, generation_status: 'FAILED', approval_status: 'FAILED', error_status,
    error_detail: scrub(errors.map((e) => e.message).join(' | ')).slice(0, 2000),
    ltx_job_id: (j.submission && j.submission.ltx_job_id) || '',
    last_checked_at: j.poll ? j.poll.last_checked_at || now : now,
    poll_attempts: j.poll ? j.poll.attempts || 0 : 0,
  } : null,
  already_responded: j.already_responded === true,
} }];
